package webhook

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestDefaultServiceResolver(t *testing.T) {
	tests := []struct {
		name    string
		sr      ServiceResolver
		namespace string
		name     string
		port     int32
		wantURL  *url.URL
		wantErr  error
	}{
		{
			name:    "empty name",
			sr:      defaultServiceResolver{},
			namespace: "default",
			name:     "",
			port:     443,
			wantURL:  nil,
			wantErr:  errors.New("cannot resolve an empty service name or namespace or port"),
		},
		{
			name:    "empty namespace",
			sr:      defaultServiceResolver{},
			namespace: "default",
			name:     "default",
			port:     443,
			wantURL:  nil,
			wantErr:  errors.New("cannot resolve an empty service name or namespace or port"),
		},
		{
			name:    "empty port",
			sr:      defaultServiceResolver{},
			namespace: "default",
			name:     "default",
			port:     0,
			wantURL:  nil,
			wantErr:  errors.New("cannot resolve an empty service name or namespace or port"),
		},
		{
			name:    "valid",
			sr:      defaultServiceResolver{},
			namespace: "default",
			name:     "default",
			port:     443,
			wantURL: &url.URL{
				Scheme: "https",
				Host:   "default.default.svc",
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			gotURL, err := tt.sr.ResolveEndpoint(tt.namespace, tt.name, tt.port)
			assert.NilError(t, err)
			assert.Equal(t, tt.wantURL, gotURL)
		})
	}
}

